def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    players_alive = 1 + len(alive_opponents)

    desperate_opponents = 0
    strong_prev_bid = 0
    avg_prev_bid = 0
    prev_count = 0
    failed_prev = 0

    for opp in alive_opponents:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 1:
            desperate_opponents += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                if bid > strong_prev_bid:
                    strong_prev_bid = bid
                avg_prev_bid += bid
                prev_count += 1
            status = prev.get('status')
            if status is not None and status != 'ok':
                failed_prev += 1
            if prev.get('error'):
                failed_prev += 1

    if prev_count > 0:
        avg_prev_bid = avg_prev_bid / prev_count

    enough_for_all = supply >= players_alive * WATER_REQ
    enough_for_two = supply >= 2 * WATER_REQ

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1

    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 2

    if not enough_for_all:
        urgency += 2
    if supply <= MIN_SUPPLY + 1:
        urgency += 1
    if desperate_opponents >= max(1, len(alive_opponents) // 2):
        urgency += 1

    if len(alive_opponents) == 0:
        base_bid = DAILY_SALARY * 0.22
    elif urgency >= 6:
        base_bid = DAILY_SALARY * 0.96
    elif urgency >= 4:
        base_bid = DAILY_SALARY * 0.82
    elif urgency >= 2:
        base_bid = DAILY_SALARY * 0.62
    else:
        if enough_for_all:
            base_bid = DAILY_SALARY * 0.28
        elif enough_for_two:
            base_bid = DAILY_SALARY * 0.45
        else:
            base_bid = DAILY_SALARY * 0.58

    if prev_count > 0:
        if strong_prev_bid >= DAILY_SALARY * 0.9:
            if urgency >= 4:
                base_bid = max(base_bid, min(DAILY_SALARY * 0.97, strong_prev_bid + 1.0))
            else:
                base_bid = min(base_bid, DAILY_SALARY * 0.35)
        elif strong_prev_bid >= DAILY_SALARY * 0.65:
            if urgency >= 2:
                base_bid = max(base_bid, min(DAILY_SALARY * 0.9, strong_prev_bid + 1.5))
        elif strong_prev_bid > 0 and urgency >= 3:
            base_bid = max(base_bid, strong_prev_bid + 1.0)

    if failed_prev > 0:
        base_bid *= 0.95

    remaining_days = max(0, 10 - day)
    reserve = 0
    if remaining_days >= 4:
        reserve = DAILY_SALARY * 1.2
    elif remaining_days >= 2:
        reserve = DAILY_SALARY * 0.6

    max_affordable = max(0, budget - reserve)
    if urgency >= 5:
        max_affordable = budget

    bid = min(base_bid, budget)
    if max_affordable > 0:
        bid = min(bid, max_affordable) if urgency < 5 else min(base_bid, budget)
    else:
        bid = min(budget, DAILY_SALARY * 0.35) if urgency < 5 else min(budget, DAILY_SALARY * 0.9)

    if hp <= 2 or no_water >= 2:
        bid = max(bid, min(budget, DAILY_SALARY * 0.9))

    if enough_for_all and urgency <= 1:
        bid = min(bid, DAILY_SALARY * 0.32)

    if bid < 0:
        bid = 0
    if bid > budget:
        bid = budget

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opponents = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opponents.append((oid, o))

    # If no opponents, take a safe moderate bid
    if not alive_opponents:
        base = DAILY_SALARY * 0.55 if my_status['hp'] > 2 else DAILY_SALARY * 0.9
        return max(0.0, min(float(my_status['budget']), float(base)))

    # Read yesterday bids from previous_trace only
    prev_bids = []
    for oid, o in alive_opponents:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Estimate how contested it was yesterday
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0
    second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid

    # Urgency based on hp and no_water_days
    hp = float(my_status['hp'])
    no_water_days = int(my_status['no_water_days'])

    urgency = 0.0
    if hp <= 2.0:
        urgency += 0.35
    elif hp <= 4.0:
        urgency += 0.15
    if no_water_days >= 2:
        urgency += 0.25
    elif no_water_days >= 1:
        urgency += 0.1

    # Supply pressure: higher supply -> bid less; lower supply -> bid more
    # Normalize between MIN_SUPPLY and MAX_SUPPLY
    if MAX_SUPPLY == MIN_SUPPLY:
        supply_factor = 0.5
    else:
        supply_factor = (supply - float(MIN_SUPPLY)) / (float(MAX_SUPPLY) - float(MIN_SUPPLY))
        if supply_factor < 0.0:
            supply_factor = 0.0
        if supply_factor > 1.0:
            supply_factor = 1.0

    # Baseline bid target
    base_low = DAILY_SALARY * 0.45
    base_high = DAILY_SALARY * 0.85
    base = base_high - (base_high - base_low) * supply_factor

    # Counter logic vs opponent aggression
    # If they bid very high yesterday, we slightly undercut to win without overspending.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        target = min(highest_prev_bid - 2.0, DAILY_SALARY * (0.78 + urgency))
        if target < DAILY_SALARY * 0.55:
            target = DAILY_SALARY * (0.62 + urgency)
    else:
        # If they were moderate, hover between their likely range and our baseline.
        # Use second-highest as a proxy for how much we need to outbid.
        proxy = second_prev_bid if second_prev_bid > 0.0 else highest_prev_bid
        target = max(base, proxy + 1.5)
        target = target * (1.0 + 0.4 * urgency)

    # Budget and hp safety caps
    budget = float(my_status['budget'])
    # If hp is very low, spend more
    if hp <= 2.0:
        cap = DAILY_SALARY * 0.95
    elif hp <= 4.0:
        cap = DAILY_SALARY * 0.85
    else:
        cap = DAILY_SALARY * 0.75

    bid = min(budget, min(cap, target))

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])
    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        if highest_prev >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3:
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            return min(my_status['budget'], DAILY_SALARY * 0.95)
        else:
            base = max(DAILY_SALARY * 0.5, highest_prev + 1.5)
            return min(my_status['budget'], base)
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.9)
    return min(my_status['budget'], DAILY_SALARY * 0.55)
